styles:
.reader-quote {
  font-style: normal;
  color: #e91e8c;
  background: rgba(233, 30, 140, 0.1);
  border-radius: 8px;
  padding: 1px 4px;
  font-weight: 500;
}
.reader-ellipsis {
  letter-spacing: 4px;
  color: #ff99cc;
}
.reader-dash {
  letter-spacing: 2px;
  opacity: 0.5;
}
.reader-speak {
  color: #4fc3f7;
  font-weight: 700;
  font-size: 1.05em;
}
